frappe.ui.form.on('Project', {
    // Trigger calculation when form is refreshed
    refresh: function(frm) {
        calculate_custom_ln_gop(frm);
    },

    // Trigger calculation when revenue fields change
    total_billable_amount: function(frm) {
        calculate_custom_ln_gop(frm);
    },

    total_sales_amount: function(frm) {
        calculate_custom_ln_gop(frm);
    },

    total_billed_amount: function(frm) {
        calculate_custom_ln_gop(frm);
    },

    // Trigger calculation when cost fields change
    total_costing_amount: function(frm) {
        calculate_custom_ln_gop(frm);
    },

    total_expense_claim: function(frm) {
        calculate_custom_ln_gop(frm);
    },

    total_purchase_cost: function(frm) {
        calculate_custom_ln_gop(frm);
    },

    custom_total_petty_expense: function(frm) {
        calculate_custom_ln_gop(frm);
    },

    total_consumed_material_cost: function(frm) {
        calculate_custom_ln_gop(frm);
    },

    custom_total_salary: function(frm) {
        calculate_custom_ln_gop(frm);
    }
});

function calculate_custom_ln_gop(frm) {
    // Get revenue values
    let total_billable_amount = frm.doc.total_billable_amount || 0;
    let total_sales_amount = frm.doc.total_sales_amount || 0;
    let total_billed_amount = frm.doc.total_billed_amount || 0;

    // Calculate total revenue based on condition
    let total_revenue = 0;
    if (total_billed_amount > 0) {
        // If total_billed_amount has value, use total_billable_amount + total_billed_amount
        total_revenue = total_billable_amount + total_billed_amount;
    } else {
        // Otherwise use total_billable_amount + total_sales_amount
        total_revenue = total_billable_amount + total_sales_amount;
    }

    // Get cost values
    let total_costing_amount = frm.doc.total_costing_amount || 0;
    let total_expense_claim = frm.doc.total_expense_claim || 0;
    let total_purchase_cost = frm.doc.total_purchase_cost || 0;
    let custom_total_petty_expense = frm.doc.custom_total_petty_expense || 0;
    let total_consumed_material_cost = frm.doc.total_consumed_material_cost || 0;
    let custom_total_salary = frm.doc.custom_total_salary || 0;

    // Calculate total costs
    let total_costs = total_costing_amount + total_expense_claim + total_purchase_cost + 
                     custom_total_petty_expense + total_consumed_material_cost + custom_total_salary;

    // Calculate custom_ln_gộp (Revenue - Costs)
    let custom_ln_gop = total_revenue - total_costs;

    // Calculate custom_per_ln_gop (Percentage)
    let custom_per_ln_gop = "0%";
    if (total_revenue > 0) {
        let percentage = (custom_ln_gop / total_revenue) * 100;
        custom_per_ln_gop = percentage.toFixed(2) + "%";
    }

    // Set the calculated values
    frm.set_value('custom_ln_gop', custom_ln_gop);
    frm.set_value('custom_per_ln_gop', custom_per_ln_gop);
}

