        // Gọi hàm tính toán khi form được tải
        if (frm.doc.employee && frm.doc.start_date && frm.doc.end_date) {
            calculate_unmarked_days(frm);
        }
    },
    employee: function(frm) {
        // Khi nhân viên thay đổi, tính toán lại
        if (frm.doc.employee && frm.doc.start_date && frm.doc.end_date) {
            calculate_unmarked_days(frm);
        }
    },
    start_date: function(frm) {
        // Khi ngày bắt đầu thay đổi, tính toán lại
        if (frm.doc.employee && frm.doc.start_date && frm.doc.end_date) {
            calculate_unmarked_days(frm);
        }
    },
    end_date: function(frm) {
        // Khi ngày kết thúc thay đổi, tính toán lại
        if (frm.doc.employee && frm.doc.start_date && frm.doc.end_date) {
            calculate_unmarked_days(frm);
        }
    }
});

function calculate_unmarked_days(frm) {
    frappe.call({
        method: 'hrms.hr.doctype.attendance.attendance.get_unmarked_days',
        args: {
            employee: frm.doc.employee,
            from_date: frm.doc.start_date,
            to_date: frm.doc.end_date,
            exclude_holidays: frm.doc.exclude_holidays || 0
        },
        callback: function(response) {
            if (response.message) {
                var unmarkedDaysCount = response.message.length; // Đếm số ngày chưa được đánh dấu
                frm.set_value('unmarked_days', unmarkedDaysCount); // Cập nhật trường OT với số ngày chưa được đánh dấu
            } else {
                frm.set_value('unmarked_days', 0); // Nếu không có ngày nào chưa được đánh dấu, đặt giá trị là 0
            }
        }
    });
}

