function set_custom_remarks(frm) {
    if (frm.doc.custom_remarks) {
        let txt = "";
        let amount = 0;
        let currency = "";

        if (frm.doc.payment_type === "Internal Transfer") {
            amount = frm.doc.paid_amount || 0;
            currency = frm.doc.paid_from_account_currency || "";
            txt = `Internal Transfer ${amount} ${currency} from ${frm.doc.paid_from || ""} to ${frm.doc.paid_to || ""}`;
        } 
        else if (frm.doc.payment_type === "Pay") {
            amount = frm.doc.paid_amount || 0;
            currency = frm.doc.paid_from_account_currency || "";
            txt = `Paid ${amount} ${currency} from ${frm.doc.paid_from || ""} to ${frm.doc.party_name || ""}`;
        } 
        else if (frm.doc.payment_type === "Receive") {
            amount = frm.doc.received_amount || 0;
            currency = frm.doc.party_account_currency || "";
            txt = `Received ${amount} ${currency} from ${frm.doc.party_name || ""} to ${frm.doc.paid_to || ""}`;
        }

        if (txt) {
            frm.set_value("remarks", txt);
        }
    }
}

