frappe.ui.form.on("Payment Entry", {
	before_submit(frm) {
		const missing_fields = [];

		if (!frm.doc.project) {
			missing_fields.push(__("Project"));
		}

		if (!frm.doc.cost_center) {
			missing_fields.push(__("Cost Center"));
		}

		if (!missing_fields.length) {
			return;
		}

		return new Promise((resolve) => {
			let continue_submit = false;
			const message = __(
				"Payment Entry này chưa nhập {0}. Bạn có muốn tiếp tục submit không?",
				[frappe.utils.comma_and(missing_fields)]
			);

			const dialog = new frappe.ui.Dialog({
				title: __("Thiếu thông tin"),
				indicator: "orange",
				primary_action_label: __("Tiếp tục Submit"),
				primary_action: () => {
					continue_submit = true;
					dialog.hide();
				},
				secondary_action_label: __("Hủy Submit"),
				secondary_action: () => {
					frappe.validated = false;
					dialog.hide();
				},
			});

			dialog.$body.append(`<p class="frappe-confirm-message">${message}</p>`);
			dialog.onhide = () => {
				if (!continue_submit) {
					frappe.validated = false;
				}
				resolve();
			};
			dialog.show();
		});
	},
});

frappe.ui.form.on("Journal Entry", {
	before_submit(frm) {
		const missing_rows = (frm.doc.accounts || [])
			.map((row) => {
				const missing_fields = [];

				if (!row.project) {
					missing_fields.push(__("Project"));
				}

				if (!row.cost_center) {
					missing_fields.push(__("Cost Center"));
				}

				return missing_fields.length
					? __("Dòng #{0}: thiếu {1}", [row.idx, frappe.utils.comma_and(missing_fields)])
					: null;
			})
			.filter(Boolean);

		if (!missing_rows.length) {
			return;
		}

		return new Promise((resolve) => {
			let continue_submit = false;
			const message = __(
				"Journal Entry này có dòng trong bảng Accounts chưa nhập Project hoặc Cost Center. Bạn có muốn tiếp tục submit không?"
			);

			const dialog = new frappe.ui.Dialog({
				title: __("Thiếu thông tin"),
				indicator: "orange",
				primary_action_label: __("Tiếp tục Submit"),
				primary_action: () => {
					continue_submit = true;
					dialog.hide();
				},
				secondary_action_label: __("Hủy Submit"),
				secondary_action: () => {
					frappe.validated = false;
					dialog.hide();
				},
			});

			dialog.$body.append(
				`<div class="frappe-confirm-message">
					<p>${message}</p>
					<ul>${missing_rows.map((row) => `<li>${row}</li>`).join("")}</ul>
				</div>`
			);

			dialog.onhide = () => {
				if (!continue_submit) {
					frappe.validated = false;
				}
				resolve();
			};

			dialog.show();
		});
	},
});
